const CACHE_VERSION="codex-v5",STATIC_PATTERN=/\/(?:vendor|public)\/.+\.(?:js|css|wasm|svg|woff2|woff|png|jpg|jpeg|gif)(?:\?.*)?$/,MAX_STATIC=200,MAX_HTML=100;self.addEventListener("install",()=>{self.skipWaiting()}),self.addEventListener("activate",n=>{n.waitUntil((async()=>{const e=await caches.keys();await Promise.all(e.filter(t=>!t.startsWith(CACHE_VERSION+"-")).map(t=>caches.delete(t))),await self.clients.claim()})())});async function trim(n,e){const t=await n.keys();if(t.length<=e)return;const a=t.length-e;for(let s=0;s<a;s++)await n.delete(t[s])}function offlinePage(){const n='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Offline \xB7 Caissa Codex</title><style>body{margin:0;font:16px/1.55 system-ui,sans-serif;background:#faf7f0;color:#1a1a1a;display:flex;min-height:100vh;align-items:center;justify-content:center;text-align:center;padding:1rem}h1{font-family:Georgia,serif}a{color:#2a5d8f}@media(prefers-color-scheme:dark){body{background:#16181d;color:#e8e6e1}a{color:#6ea3d4}}</style></head><body><main><h1>You are offline</h1><p>This page hasn\u2019t been saved on this device yet.<br>The openings you have opened before still work without a connection.</p><p><a href="/">Try the home page</a></p></main></body></html>';return new Response(n,{status:503,headers:{"Content-Type":"text/html; charset=utf-8"}})}self.addEventListener("fetch",n=>{const e=n.request;if(e.method!=="GET"||e.destination==="worker"||e.destination==="sharedworker")return;const t=new URL(e.url);if(t.origin===self.location.origin&&!(t.pathname.startsWith("/api/")||t.pathname==="/admin"||t.pathname.startsWith("/admin/")||t.pathname==="/sitemap.xml"||t.pathname==="/robots.txt")){if(STATIC_PATTERN.test(t.pathname)||t.pathname==="/og.php"){n.respondWith((async()=>{const a=await caches.open(CACHE_VERSION+"-static"),s=await a.match(e);if(s&&t.searchParams.has("v"))return s;const i=fetch(e).then(async o=>(o&&o.status===200&&(await a.put(e,o.clone()),await trim(a,200)),o)).catch(()=>null);return s||await i||new Response("Offline",{status:504})})());return}n.respondWith((async()=>{try{const a=await fetch(e),s=a&&a.headers.get("Content-Type")||"";if(a&&a.status===200&&s.startsWith("text/html")){const i=await caches.open(CACHE_VERSION+"-html");await i.put(e,a.clone()),await trim(i,100)}return a}catch{return await caches.match(e)||offlinePage()}})())}});
